{
  "interpretation": {
    "name": "TightenLine1F25WithSharedNutrunner",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring the shared nutrunner NR7 to station st1, tighten the F25 fasteners with the MES program, evaluate and record the result, then return the tool to the crib.",
    "constraints": [
      "NR7 must be reserved before any use and released at the end",
      "transport-tool must be delegated to the Executor agvexecutor",
      "NR7 must be at st1 before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program; no torque or tolerance literals in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "NR7 must be returned to the crib after the tightening"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-f25-tightening-with-nr7",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "DeliverTool",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "get-f25-program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "DeliverTool",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "EvaluateAndRecord",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-f25"], "dep": ["get-f25-program", "reserve-nr7", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten-f25", "service": "tighten-fasteners", "next": [], "dep": ["configure-nr7", "reserve-nr7", "transport-to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "EvaluateAndRecord",
        "next": "ReturnTool",
        "steps": [
          {"name": "evaluate-f25", "service": "evaluate-tightening", "next": [], "dep": ["tighten-f25", "get-f25-program"], "executor": null, "params": {}},
          {"name": "record-f25", "service": "record-tightening", "next": [], "dep": ["tighten-f25"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnTool",
        "next": "ReleaseTool",
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "ReleaseTool",
        "next": null,
        "steps": [
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
